import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

// Generated by `marmeon make:auth` — a form with named fields must say it posts: before the page is interactive (or when its
// script fails to load), Enter submits a form without `method` as a GET, and the fields land in the address — a password in the
// history and in logs. A form without named fields sends nothing that way.

const views = new URL('./views/', import.meta.url);

describe('the forms of the views', () => {
  it('post whenever a field has a name', () => {
    const offenders: string[] = [];
    for (const file of readdirSync(views).filter((name) => name.endsWith('.tsx'))) {
      const source = readFileSync(new URL(file, views), 'utf8');
      for (const [form] of source.matchAll(/<form\b[\s\S]*?<\/form>/g)) {
        // The attributes come before `onSubmit`, whose arrow function has a `>` of its own.
        const attributes = form.slice(0, form.indexOf('onSubmit'));
        if (/\sname=/.test(form) && !/\smethod="post"/.test(attributes)) offenders.push(file);
      }
    }
    expect(offenders, 'a form with named fields and no method="post"').toEqual([]);
  });
});
